package android.location;import java.util.*;import android.os.Looper;public class LocationManager {public static final String GPS_PROVIDER="gps",NETWORK_PROVIDER="network";public final List<LocationListener> active=new ArrayList<>();public int registrations,removals;public List<String> getAllProviders(){return List.of(GPS_PROVIDER,NETWORK_PROVIDER);}public void requestLocationUpdates(String p,long t,float d,LocationListener l,Looper lo){registrations++;if(!active.contains(l))active.add(l);}public void removeUpdates(LocationListener l){removals++;active.remove(l);}}
